CREATE FUNCTION public.fn_folha_dia_contexto_v3(p_data date,p_obra_id uuid,p_person_id uuid,p_kind text DEFAULT 'primeline') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $day$
DECLARE u public.utilizadores;c public.colaboradores;e public.folha_externos;ev public.folha_avaliacoes_diarias;ref jsonb;reference jsonb;records jsonb;refs jsonb;all_count integer;own boolean;can_write boolean;cut date;
BEGIN
 u:=folha_privado.ator();IF p_data IS NULL OR NOT isfinite(p_data) OR p_person_id IS NULL OR p_kind IS NULL OR p_kind NOT IN('primeline','external') THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;IF NOT EXISTS(SELECT 1 FROM public.obras WHERE id=p_obra_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: tenant obra' USING ERRCODE='42501';END IF;PERFORM folha_privado.destino_autorizar_v3(p_person_id,p_obra_id,p_kind,false);
 IF p_kind='primeline' THEN SELECT * INTO c FROM public.colaboradores WHERE id=p_person_id AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;own:=c.utilizador_id=u.id AND (SELECT count(*) FROM public.colaboradores WHERE utilizador_id=u.id AND empresa_id=u.empresa_id)=1;
  IF NOT folha_privado.admin() AND NOT folha_privado.elegivel_equipa(p_person_id,p_data) AND NOT own AND NOT EXISTS(SELECT 1 FROM public.folha_registos WHERE colaborador_id=p_person_id AND obra_id=p_obra_id AND data=p_data) AND NOT EXISTS(SELECT 1 FROM public.folha_referencias WHERE colaborador_id=p_person_id AND origem_obra_id=p_obra_id AND data=p_data AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: âmbito da pessoa' USING ERRCODE='42501';END IF;
  SELECT * INTO ev FROM public.folha_avaliacoes_diarias WHERE colaborador_id=p_person_id AND data=p_data AND empresa_id=u.empresa_id;SELECT avaliacao_diaria_data_ativacao INTO cut FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id;
  IF ev.referencia_estado='capturada' THEN ref:=jsonb_build_object('referencia_estado','capturada','expected_minutes',ev.expected_minutes,'horario_snapshot',ev.horario_snapshot,'identity',ev.id);
  ELSIF cut IS NOT NULL THEN ref:=folha_privado.diaria_referencia(p_person_id,p_data);ELSE ref:=jsonb_build_object('referencia_estado','pendente','referencia_motivo','mecanismo_diario_nao_ativado');END IF;
  reference:=CASE WHEN ref->>'referencia_estado'='capturada' THEN jsonb_build_object('confirmed',true,'version_id',coalesce(ref->>'identity',ref->>'jornada_versao_id',ref->>'horario_versao_id'),'effective_from',p_data,'effective_to',p_data+1,'day',jsonb_build_object('day_type',coalesce(ref->'horario_snapshot'->>'day_type','prevista'),'expected_minutes',ref->'expected_minutes','intervals',ref->'horario_snapshot'->'intervals')) ELSE jsonb_build_object('confirmed',false,'reason',ref->>'referencia_motivo') END;
  can_write:=c.data_admissao<=p_data AND (c.data_saida IS NULL OR c.data_saida>p_data) AND (folha_privado.adm_operacional() OR u.funcao='encarregado' AND (folha_privado.elegivel_equipa(p_person_id,p_data) OR own) OR own AND u.funcao IN('diretor_obra','adjunto','preparador'));
 ELSE SELECT * INTO e FROM public.folha_externos WHERE id=p_person_id AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: externo' USING ERRCODE='42501';END IF;reference:=NULL;can_write:=(e.ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.externo_id=p_person_id AND f.obra_id=p_obra_id AND f.data=p_data AND f.empresa_id=u.empresa_id)) AND (folha_privado.adm_operacional() OR u.funcao IN('encarregado','diretor_obra')) AND (EXISTS(SELECT 1 FROM public.folha_externos_dias WHERE externo_id=p_person_id AND obra_id=p_obra_id AND data=p_data) OR EXISTS(SELECT 1 FROM public.folha_externos_permanencias WHERE externo_id=p_person_id AND obra_id=p_obra_id AND inicio<=p_data AND (fim IS NULL OR fim>p_data)));
 END IF;
 can_write:=coalesce(can_write,false) AND p_data<=(now() AT TIME ZONE 'Europe/Lisbon')::date AND (p_data>=(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR folha_privado.adm_operacional() OR p_kind='external' AND u.funcao='diretor_obra');
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.obra_id),'[]') INTO records FROM public.folha_registos f WHERE f.empresa_id=u.empresa_id AND f.data=p_data AND CASE WHEN p_kind='primeline' THEN f.colaborador_id=p_person_id ELSE f.externo_id=p_person_id END AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=f.obra_id AND utilizador_id=u.id AND papel=u.funcao));
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO refs FROM public.folha_referencias r WHERE r.empresa_id=u.empresa_id AND r.data=p_data AND CASE WHEN p_kind='primeline' THEN r.colaborador_id=p_person_id ELSE r.externo_id=p_person_id END AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=r.origem_obra_id AND utilizador_id=u.id AND papel=u.funcao));
 SELECT count(*) INTO all_count FROM (SELECT id FROM public.folha_registos WHERE data=p_data AND CASE WHEN p_kind='primeline' THEN colaborador_id=p_person_id ELSE externo_id=p_person_id END UNION ALL SELECT id FROM public.folha_referencias WHERE data=p_data AND CASE WHEN p_kind='primeline' THEN colaborador_id=p_person_id ELSE externo_id=p_person_id END) q;
 RETURN jsonb_build_object('version',3,'person_id',p_person_id,'kind',p_kind,'work_id',p_obra_id,'date',p_data,'name',coalesce(c.nome,e.nome),'server_date',(now() AT TIME ZONE 'Europe/Lisbon')::date,'records',records,'references',refs,'hidden_record_count',all_count-jsonb_array_length(records)-jsonb_array_length(refs),'reference',reference,'reference_edit_capability',false,'expected_daily_revision',coalesce(ev.revision,0),'can_write',can_write,'requires_reason',p_data<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR p_kind='external' AND u.funcao='diretor_obra','can_report_faltou',u.funcao='encarregado' AND p_kind='primeline' AND NOT coalesce(own,false) AND all_count=0 AND p_data BETWEEN (now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND (now() AT TIME ZONE 'Europe/Lisbon')::date AND EXISTS(SELECT 1 FROM public.quadro_equipa_permanencias WHERE colaborador_id=p_person_id AND obra_id=p_obra_id AND empresa_id=u.empresa_id AND inicio<=p_data AND (fim IS NULL OR fim>p_data)) AND NOT EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p_person_id AND data=p_data),'has_absence',p_kind='primeline' AND EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p_person_id AND data=p_data));
END $day$;
CREATE FUNCTION public.fn_folha_destinos_contexto_v3() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $works$
DECLARE u public.utilizadores;works jsonb;BEGIN u:=folha_privado.ator();IF NOT folha_privado.admin() AND u.funcao NOT IN('encarregado','diretor_obra','adjunto','preparador') THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'number',o.numero,'name',o.nome,'status',o.situacao) ORDER BY o.numero),'[]') INTO works FROM public.obras o WHERE o.empresa_id=u.empresa_id AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis r WHERE r.obra_id=o.id AND r.utilizador_id=u.id AND r.papel=u.funcao));RETURN jsonb_build_object('version',3,'works',works);END $works$;
REVOKE ALL ON FUNCTION public.fn_folha_dia_contexto_v3(date,uuid,uuid,text),public.fn_folha_destinos_contexto_v3() FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.fn_folha_dia_contexto_v3(date,uuid,uuid,text),public.fn_folha_destinos_contexto_v3() TO authenticated;
CREATE FUNCTION public.fn_folha_equipa_horas_contexto_v3(p_data date,p_obra_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $team$
DECLARE u public.utilizadores;b jsonb;person record;people jsonb:='[]';BEGIN
 u:=folha_privado.ator();b:=public.fn_folha_horas_contexto_v3(p_data,p_obra_id);
 FOR person IN SELECT person_id,kind FROM (SELECT (x->>'person_id')::uuid person_id,'primeline'::text kind FROM jsonb_array_elements(b->'rows') x UNION SELECT (x->>'person_id')::uuid,'external' FROM jsonb_array_elements(b->'external_rows') x UNION SELECT coalesce(colaborador_id,externo_id),CASE WHEN colaborador_id IS NULL THEN 'external' ELSE 'primeline' END FROM public.folha_referencias WHERE empresa_id=u.empresa_id AND origem_obra_id=p_obra_id AND data=p_data UNION SELECT coalesce(colaborador_id,externo_id),CASE WHEN colaborador_id IS NULL THEN 'external' ELSE 'primeline' END FROM public.folha_registos WHERE empresa_id=u.empresa_id AND obra_id=p_obra_id AND data=p_data) q ORDER BY kind,person_id LOOP
  people:=people||jsonb_build_array(public.fn_folha_dia_contexto_v3(p_data,p_obra_id,person.person_id,person.kind));
 END LOOP;RETURN jsonb_build_object('version',3,'date',p_data,'work_id',p_obra_id,'people',people,'works',public.fn_folha_destinos_contexto_v3()->'works','base',b);
END $team$;
REVOKE ALL ON FUNCTION public.fn_folha_equipa_horas_contexto_v3(date,uuid) FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.fn_folha_equipa_horas_contexto_v3(date,uuid) TO authenticated;
